# Migrating Flat Pulumi Program to ComponentResource

## Before: Flat Program

```typescript
// index.ts (flat)
import * as aws from "@pulumi/aws";
import * as eks from "@pulumi/eks";
import * as pulumi from "@pulumi/pulumi";

const config = new pulumi.Config();
const env = pulumi.getStack(); // "dev" or "prod"

const nodeCount = config.getNumber("nodeCount") ?? 2;
const nodeType = config.get("nodeType") ?? "t3.medium";
const dbClass = config.get("dbClass") ?? "db.t3.micro";
const multiAz = config.getBoolean("multiAz") ?? false;

// --- Cluster ---
const cluster = new eks.Cluster("app-cluster", {
    desiredCapacity: nodeCount,
    minSize: nodeCount,
    maxSize: nodeCount * 2,
    instanceType: nodeType,
});

// --- Bucket ---
const bucket = new aws.s3.Bucket("app-assets", {
    versioning: { enabled: true },
    serverSideEncryptionConfiguration: {
        rule: {
            applyServerSideEncryptionByDefault: {
                sseAlgorithm: "AES256",
            },
        },
    },
});

new aws.s3.BucketPublicAccessBlock("app-assets-pab", {
    bucket: bucket.id,
    blockPublicAcls: true,
    blockPublicPolicy: true,
    ignorePublicAcls: true,
    restrictPublicBuckets: true,
});

// --- RDS ---
const dbSubnetGroup = new aws.rds.SubnetGroup("app-db-subnets", {
    subnetIds: cluster.core.vpc.privateSubnetIds,
});

const db = new aws.rds.Instance("app-db", {
    engine: "postgres",
    engineVersion: "15",
    instanceClass: dbClass,
    allocatedStorage: 20,
    multiAz: multiAz,
    dbSubnetGroupName: dbSubnetGroup.name,
    deletionProtection: true,
    backupRetentionPeriod: 7,
    publiclyAccessible: false,
    storageEncrypted: env === "prod",
    skipFinalSnapshot: env === "dev",
    username: "appadmin",
    password: config.requireSecret("dbPassword"),
});

// --- IAM ---
const iamUser = new aws.iam.User("app-sa");
const accessKey = new aws.iam.AccessKey("app-sa-key", { user: iamUser.name });

const iamPolicy = new aws.iam.Policy("app-sa-policy", {
    policy: bucket.arn.apply(arn => JSON.stringify({
        Version: "2012-10-17",
        Statement: [{
            Effect: "Allow",
            Action: ["s3:GetObject", "s3:PutObject"],
            Resource: [`${arn}/*`],
        }],
    })),
});

new aws.iam.UserPolicyAttachment("app-sa-attach", {
    user: iamUser.name,
    policyArn: iamPolicy.arn,
});

// --- Secret ---
const dbConnectionString = new pulumi.ConfigSecret("db", {
    connectionString: pulumi.interpolate`postgresql://${db.username}:${db.password}@${db.endpoint}/appdb`,
});

// --- HTTPS (prod: CloudFront + ACM) ---
if (env === "prod") {
    const cert = new aws.acm.Certificate("app-cert", {
        domainName: config.require("domain"),
        validationMethod: "DNS",
    });

    const distribution = new aws.cloudfront.Distribution("app-cdn", {
        origins: [{
            domainName: bucket.bucketRegionalDomainName,
            originId: "s3-origin",
        }],
        enabled: true,
        viewerCertificate: {
            acmCertificateArn: cert.arn,
            sslSupportMethod: "sni-only",
        },
        defaultCacheBehavior: {
            targetOriginId: "s3-origin",
            viewerProtocolPolicy: "redirect-to-https",
            allowedMethods: ["GET", "HEAD"],
            cachedMethods: ["GET", "HEAD"],
            forwardedValues: {
                queryString: false,
                cookies: { forward: "none" },
            },
        },
        restrictions: {
            geoRestriction: { restrictionType: "none" },
        },
    });
}

export const kubeconfig = cluster.kubeconfig;
export const bucketName = bucket.bucket;
export const dbEndpoint = db.endpoint;
```

## After: ComponentResource with Aliases

```typescript
// appStack.ts
import * as aws from "@pulumi/aws";
import * as eks from "@pulumi/eks";
import * as pulumi from "@pulumi/pulumi";

export interface AppStackArgs {
    env: string;
    nodeCount: number;
    nodeType: string;
    dbClass: string;
    multiAz: boolean;
    dbPassword: pulumi.Input<string>;
    domain?: pulumi.Input<string>;
}

export class AppStack extends pulumi.ComponentResource {
    public readonly kubeconfig: pulumi.Output<any>;
    public readonly bucketName: pulumi.Output<string>;
    public readonly dbEndpoint: pulumi.Output<string>;

    constructor(name: string, args: AppStackArgs, opts?: pulumi.ComponentResourceOptions) {
        super("custom:infra:AppStack", name, {}, opts);

        const componentOpts = { parent: this };

        // --- Cluster ---
        // Flat URN: urn:pulumi:dev::project::eks:index:Cluster::app-cluster
        // New URN:  urn:pulumi:dev::project::custom:infra:AppStack$eks:index:Cluster::app::app-cluster
        const cluster = new eks.Cluster("app-cluster", {
            desiredCapacity: args.nodeCount,
            minSize: args.nodeCount,
            maxSize: args.nodeCount * 2,
            instanceType: args.nodeType,
        }, {
            ...componentOpts,
            aliases: [{ parent: pulumi.rootStackResource }],
        });

        // --- Bucket ---
        const bucket = new aws.s3.Bucket("app-assets", {
            versioning: { enabled: true },
            serverSideEncryptionConfiguration: {
                rule: {
                    applyServerSideEncryptionByDefault: {
                        sseAlgorithm: "AES256",
                    },
                },
            },
        }, {
            ...componentOpts,
            aliases: [{ parent: pulumi.rootStackResource }],
        });

        new aws.s3.BucketPublicAccessBlock("app-assets-pab", {
            bucket: bucket.id,
            blockPublicAcls: true,
            blockPublicPolicy: true,
            ignorePublicAcls: true,
            restrictPublicBuckets: true,
        }, {
            ...componentOpts,
            aliases: [{ parent: pulumi.rootStackResource }],
        });

        // --- RDS ---
        const dbSubnetGroup = new aws.rds.SubnetGroup("app-db-subnets", {
            subnetIds: cluster.core.vpc.privateSubnetIds,
        }, {
            ...componentOpts,
            aliases: [{ parent: pulumi.rootStackResource }],
        });

        const db = new aws.rds.Instance("app-db", {
            engine: "postgres",
            engineVersion: "15",
            instanceClass: args.dbClass,
            allocatedStorage: 20,
            multiAz: args.multiAz,
            dbSubnetGroupName: dbSubnetGroup.name,
            deletionProtection: true,
            backupRetentionPeriod: 7,
            publiclyAccessible: false,
            storageEncrypted: args.env === "prod",
            skipFinalSnapshot: args.env === "dev",
            username: "appadmin",
            password: args.dbPassword,
        }, {
            ...componentOpts,
            aliases: [{ parent: pulumi.rootStackResource }],
        });

        // --- IAM ---
        const iamUser = new aws.iam.User("app-sa", {}, {
            ...componentOpts,
            aliases: [{ parent: pulumi.rootStackResource }],
        });

        const accessKey = new aws.iam.AccessKey("app-sa-key", {
            user: iamUser.name,
        }, {
            ...componentOpts,
            aliases: [{ parent: pulumi.rootStackResource }],
        });

        const iamPolicy = new aws.iam.Policy("app-sa-policy", {
            policy: bucket.arn.apply(arn => JSON.stringify({
                Version: "2012-10-17",
                Statement: [{
                    Effect: "Allow",
                    Action: args.env === "prod"
                        ? ["s3:GetObject"]  // least-privilege on prod
                        : ["s3:GetObject", "s3:PutObject"],
                    Resource: [`${arn}/*`],
                }],
            })),
        }, {
            ...componentOpts,
            aliases: [{ parent: pulumi.rootStackResource }],
        });

        new aws.iam.UserPolicyAttachment("app-sa-attach", {
            user: iamUser.name,
            policyArn: iamPolicy.arn,
        }, {
            ...componentOpts,
            aliases: [{ parent: pulumi.rootStackResource }],
        });

        // --- HTTPS (prod only) ---
        if (args.env === "prod" && args.domain) {
            const cert = new aws.acm.Certificate("app-cert", {
                domainName: args.domain,
                validationMethod: "DNS",
            }, {
                ...componentOpts,
                aliases: [{ parent: pulumi.rootStackResource }],
            });

            new aws.cloudfront.Distribution("app-cdn", {
                origins: [{
                    domainName: bucket.bucketRegionalDomainName,
                    originId: "s3-origin",
                }],
                enabled: true,
                viewerCertificate: {
                    acmCertificateArn: cert.arn,
                    sslSupportMethod: "sni-only",
                },
                defaultCacheBehavior: {
                    targetOriginId: "s3-origin",
                    viewerProtocolPolicy: "redirect-to-https",
                    allowedMethods: ["GET", "HEAD"],
                    cachedMethods: ["GET", "HEAD"],
                    forwardedValues: {
                        queryString: false,
                        cookies: { forward: "none" },
                    },
                },
                restrictions: {
                    geoRestriction: { restrictionType: "none" },
                },
            }, {
                ...componentOpts,
                aliases: [{ parent: pulumi.rootStackResource }],
            });
        }

        this.kubeconfig = cluster.kubeconfig;
        this.bucketName = bucket.bucket;
        this.dbEndpoint = db.endpoint;

        this.registerOutputs({
            kubeconfig: this.kubeconfig,
            bucketName: this.bucketName,
            dbEndpoint: this.dbEndpoint,
        });
    }
}
```

```typescript
// index.ts
import * as pulumi from "@pulumi/pulumi";
import { AppStack } from "./appStack";

const config = new pulumi.Config();
const env = pulumi.getStack();

const app = new AppStack("app", {
    env,
    nodeCount: config.getNumber("nodeCount") ?? 2,
    nodeType: config.get("nodeType") ?? "t3.medium",
    dbClass: config.get("dbClass") ?? "db.t3.micro",
    multiAz: config.getBoolean("multiAz") ?? false,
    dbPassword: config.requireSecret("dbPassword"),
    domain: config.get("domain"),
});

export const kubeconfig = app.kubeconfig;
export const bucketName = app.bucketName;
export const dbEndpoint = app.dbEndpoint;
```

## Stack Configs

```yaml
# Pulumi.dev.yaml
config:
  project:nodeCount: 2
  project:nodeType: t3.medium
  project:dbClass: db.t3.micro
  project:multiAz: false
  project:dbPassword:
    secure: AAABAK...  # encrypted via Pulumi secrets
```

```yaml
# Pulumi.prod.yaml
config:
  project:nodeCount: 4
  project:nodeType: t3.large
  project:dbClass: db.t3.medium
  project:multiAz: true
  project:domain: app.example.com
  project:dbPassword:
    secure: AAABAK...  # encrypted via Pulumi secrets
```

## How Aliases Prevent Replacement

Every resource that was previously at the stack root gets `aliases: [{ parent: pulumi.rootStackResource }]`. This tells Pulumi:

| | Before (flat) | After (component) |
|---|---|---|
| **URN** | `...::project::eks:index:Cluster::app-cluster` | `...::project::custom:infra:AppStack$eks:index:Cluster::app::app-cluster` |
| **Alias matches** | ✅ old URN registered as alias | new canonical URN |

Pulumi sees the alias, recognizes it as the same resource, and performs an **in-place update** (no destroy/create). After the first successful `pulumi up`, the aliases can optionally be removed in a subsequent refactor.

## Verification

```bash
# Preview should show no replacements
pulumi preview --diff
# Expected: ~ updates only, +- 0 replacements
```
